const agentOut = ($input.first().json.output) || '';
const trig = $('Telegram Trigger').first().json || {};
const chatId = (trig.message && trig.message.chat && trig.message.chat.id)
  || (trig.callback_query && trig.callback_query.message && trig.callback_query.message.chat && trig.callback_query.message.chat.id);
const needsApproval = /\[\[CONFIRM\]\]/.test(agentOut);
const text = agentOut.replace(/\s*\[\[CONFIRM\]\]\s*/g, '').trim();
return [{ json: { text, needsApproval, chatId } }];
